desktopweb.customCSS:
input:focus-visible{
    outline: none;
  }
  textarea:focus-visible{
    outline: #293276 auto 1px;
  }
  div[kw="Calendar"]>img{
  padding: 2.5% !important;
  }
  .btnSkipNavigation {
      transform: translateY(-1000px);
  }
  .btnSkipNavigation:focus-visible {
      transform: translateY(0px);
  }
  .btnMenu,.btnMenu-focus{
    background-size: 25px 25px !important;
    background-position: center !important;
  }
  .txtAreaResize{
    resize:both !important;
    border: 1px solid;
    max-width: 90%;
  }
div[kw="FlexContainer"]:focus-visible {
outline: #293276 auto 1px;
    outline-offset: -2px;
}
img:focus-visible {
outline: #293276 auto 1px;
outline-offset: 4px;
}
button[kw="Button"]:focus-visible {
outline: #293276 auto 1px;
outline-offset: 3px;
}

